cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c4.lua <<'EOF'
pA2 = pile{{"lead white",3},{"smalt",2.5},{"Prussian blue",0.2},{"red earth",0.08}}
pB2 = pile{{"lead white",5},{"smalt",1.3},{"vermilion",0.12},{"yellow ochre",0.1}}
pD2 = pile{{"lead white",4},{"chrome yellow",1.1},{"vermilion",0.4},{"red earth",0.08}}
local opt = function(p, cov) return {hand="body", tool="filbert 14", pile=p, angle=0.02, angle_jitter=0.1, coverage=cov, fill=true, length={70,180}} end
work(skyA:shrink(4), opt(pA2, 2.5))
work(skyB:shrink(4), opt(pB2, 2))
work(skyD:shrink(3), opt(pD2, 2.5))
EOF
timeout 1200 bin/easel do -f $TMPDIR/c4.lua --look

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Sky laid in four bands and blended wet: cool smalt top to chrome/vermilion glow at the horizon. Came out paler than piles as expected. Soft violet cloud streaks laid wet and blended with a badger: they read pinkish and pale, will darken the undersides later. Water in three bands (warm glow under the horizon, lavender, blue-grey) blended. Everything high key now; the darks of land and trees will set the key. Waiting a day before painting darks over."
timeout 600 bin/easel do 'print(wait(26*60)); print(drying(500,100), drying(500,400), drying(500,650), drying(500,215))'

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c13.lua <<'EOF'
local top = {{280,440},{330,441},{380,443},{430,442},{460,436},{470,428},{482,424},{495,427},{505,433},{520,430},{532,434},{545,441},{600,444},{680,445},{740,443},{770,446},{830,445},{862,438},{870,430},{884,426},{896,429},{905,436},{915,440},{960,443},{1000,442}}
local bot = function(x) return 458 + 2*math.sin(x/60) end
bank = below(top) * above(bot)
bank = bank:roughen(2.5, 25, 13, 0)
pBank = pile{{"raw umber",2},{"green earth",1},{"yellow ochre",0.5},{"lead white",0.8},{"smalt",0.4}}
work(bank, {hand="body", tool="filbert 5", pile=pBank, angle=0, angle_jitter=0.2, coverage=3, fill=true, length={15,50}, edge="firm"})
EOF
timeout 1200 bin/easel do -f $TMPDIR/c13.lua && bin/easel look --crop 300,380,800,500

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c14.lua <<'EOF'
treeO = outline{{-10,480,"c"},{-10,190,"c"},{20,172},{45,150},{75,128},{105,122},{130,138},{150,150},{175,142},{200,158},{222,178},{240,200},{262,215},{280,240},{290,268},{305,285},{318,310},{326,335},{340,360},{345,385},{356,405},{368,425},{385,440},{395,452},{400,466,"c"},{200,478},{60,484}, closed=true, char="soft", seed=21, lobe=18, amount=1.2}
trees = treeO:mask()
pDark = pile{{"Prussian blue",0.4},{"yellow ochre",1.2},{"raw umber",1.5},{"bone black",0.4}}
work(trees, {hand="body", tool="filbert 10", pile=pDark, angle=function(x,y) return 0.6*math.sin(x/40+y/55) end, angle_jitter=0.5, coverage=3.5, load=0.9, fill=true, length={20,50}, edge="soft"})
EOF
timeout 1200 bin/easel do -f $TMPDIR/c14.lua --look

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c15.lua <<'EOF'
local tall = outline{{-10,200,"c"},{-10,110},{15,85},{40,62},{62,48},{85,52},{100,70},{112,95},{120,125},{110,150},{60,170}, closed=true, char="soft", seed=31, lobe=14, amount=1.3}
local small = outline{{380,462,"c"},{384,440},{392,420},{404,405},{418,398},{432,404},{442,420},{446,440},{450,458,"c"}, closed=true, char="soft", seed=32, lobe=8, amount=1.2}
crowns = tall:mask() + small:mask()
work(crowns, {hand="body", tool="filbert 8", pile=pDark, angle=function(x,y) return 0.6*math.sin(x/40+y/55) end, angle_jitter=0.5, coverage=3.5, load=0.9, fill=true, length={15,40}, edge="soft"})
trees = trees + crowns
EOF
timeout 1200 bin/easel do -f $TMPDIR/c15.lua --look

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c17.lua <<'EOF'
reflO = outline{{-10,470,"c"},{458,466,"c"},{452,480},{438,500},{420,512},{398,520},{388,540},{370,560},{352,580},{345,605},{330,630},{318,650},{300,668},{285,690},{275,720,"c"},{-10,720,"c"}, closed=true, char="soft", seed=51, lobe=14, amount=1.0}
refl = reflO:mask()
pRefl = pile{{"Prussian blue",0.35},{"yellow ochre",1},{"raw umber",1.5},{"bone black",0.3},{"lead white",0.5},{"smalt",0.4}}
work(refl, {hand="body", tool="filbert 10", pile=pRefl, angle=math.pi/2, angle_jitter=0.15, coverage=3.2, load=0.9, fill=true, length={25,70}, edge="soft"})
blend(refl, {angle=0, angle_jitter=0.03, tool="badger 30", clip=true})
EOF
timeout 1200 bin/easel do -f $TMPDIR/c17.lua --look

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Day 3: distant hill (lavender) and far bank strip laid over dry sky. Big tree mass on left in a no-white dark (Prussian, ochre, umber, black) plus a taller crown and a small separate tree. Reads as one lobed cauliflower blob; foliage lights stippled wet dissolved into it as the notes warned. Tree reflection laid over the dry water came out far too pale and green-grey (white + smalt in the pile). Waiting for it all to set, then: darken reflection, break the tree silhouette, add lit foliage and sky holes."
timeout 600 bin/easel do 'print(wait(30*60)); print(drying(100,300), drying(150,600), drying(420,420), drying(700,445))'

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Blending softened but did not dissolve the pattern. Rethink: the light is low and behind the tree (glow at the right horizon), so the tree is contre-jour, nearly a silhouette. Once set, I'll repaint the whole interior in darks varied by noise (warmer/cooler), and keep lights only as a faint warm rim on the side facing the glow."
timeout 600 bin/easel do 'print(wait(30*60)); print(drying(80,230), drying(200,330), drying(400,300))'

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c35.lua <<'EOF'
local inner = trees:shrink(10)
nz = noise{seed=77, octaves=4, period=90, persistence=0.55}
warmPart = inner * mask(function(x,y) return nz(x,y) > 0.05 and 1 or 0 end)
coolPart = inner - warmPart
pTW = pile{{"Prussian blue",0.3},{"yellow ochre",1.3},{"raw umber",1.6},{"bone black",0.35},{"green earth",0.4}}
pTC = pile{{"Prussian blue",0.5},{"yellow ochre",0.8},{"raw umber",1.4},{"bone black",0.55}}
local ang = function(x,y) return 0.9*math.sin(x/35 + y/50) end
work(coolPart, {hand="body", tool="filbert 9", pile=pTC, angle=ang, angle_jitter=0.6, coverage=3.2, load=0.9, fill=true, length={12,35}, edge="soft"})
work(warmPart, {hand="body", tool="filbert 9", pile=pTW, angle=ang, angle_jitter=0.6, coverage=3.2, load=0.9, fill=true, length={12,35}, edge="soft"})
EOF
timeout 1200 bin/easel do -f $TMPDIR/c35.lua && bin/easel look --crop 0,30,480,480

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c39.lua <<'EOF'
refl2O = outline{{-10,466,"c"},{466,466,"c"},{470,478},{462,490},{466,500},{450,511},{434,518},{424,532},{426,546},{408,558},{396,574},{392,592},{376,606},{372,624},{358,640},{352,660},{336,676},{330,698},{322,720,"c"},{-10,720,"c"}, closed=true, char="soft", seed=81, lobe=10, amount=1.0}
refl2 = refl2O:mask()
local nz2 = noise{seed=88, octaves=3, period=120, stretch={0, 4}}
local upper = refl2 * above(function(x) return 560 end)
local lower = refl2 - upper
pR1 = pile{{"Prussian blue",0.45},{"yellow ochre",1.0},{"raw umber",1.6},{"bone black",0.5},{"smalt",0.2}}
pR2 = pile{{"Prussian blue",0.4},{"yellow ochre",1.0},{"raw umber",1.4},{"bone black",0.35},{"smalt",0.4},{"lead white",0.12}}
work(upper, {hand="body", tool="filbert 12", pile=pR1, angle=0, angle_jitter=0.05, coverage=3.5, load=0.95, fill=true, length={40,110}, edge="soft"})
work(lower, {hand="body", tool="filbert 12", pile=pR2, angle=0, angle_jitter=0.05, coverage=3.2, load=0.9, fill=true, length={40,110}, edge="soft"})
blend(refl2, {angle=0, angle_jitter=0.02, tool="badger 30", pressure={0.25,0.45}})
EOF
timeout 1200 bin/easel do -f $TMPDIR/c39.lua --look

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Cloud bars came out as flat sausages; an unclipped horizontal badger blend turned them into soft mauve streaks with blobby finger-ends. Their value sits too close to the sky. Once tacky: darker violet cores with long thin strokes, lit peach undersides, sky-coloured cuts to break the ends."
timeout 600 bin/easel do 'print(wait(24*60)); print(drying(600,170), drying(600,300), drying(200,460), drying(200,520))'

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Thin scratchy cores dragged over tacky cloud paint came out as stick-and-slip scribbles (as studio notes warned). Plan: repaint the clouds as whole new bodies over the tacky layer - fuller shapes covering the old finger-ends, a darker violet core, warm peach undersides, then blend that fresh layer wet."
bin/easel look --grid 50

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c45.lua <<'EOF'
pV1 = pile{{"lead white",2.2},{"smalt",1},{"red earth",0.4},{"raw umber",0.3},{"vermilion",0.05}}
pV2 = pile{{"lead white",2.8},{"smalt",0.9},{"red earth",0.35},{"raw umber",0.2},{"vermilion",0.1}}
pV3 = pile{{"lead white",3.5},{"smalt",0.6},{"vermilion",0.25},{"red earth",0.2},{"chrome yellow",0.1}}
local cut = K1 - trees
local o = function(p) return {hand="body", tool="filbert 10", pile=p, angle=0, angle_jitter=0.04, coverage=3, load=0.85, fill=true, length={50,140}, edge="soft"} end
work(cut, o(pV1))
work(K2, o(pV2))
work(K3, o(pV3))
EOF
timeout 1200 bin/easel do -f $TMPDIR/c45.lua --look

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c52.lua <<'EOF'
local top = {{-10,440}}
local x = -10
while x < 470 do
  x = x + rand(10, 28)
  top[#top+1] = {x, 438 + rand(-8, 6) + (x > 380 and (x-380)*0.15 or 0)}
end
top[#top+1] = {478, 462}
local bot = {}
for xx = -10, 480, 15 do bot[#bot+1] = {xx, 469 + rand(-1.5, 1.5)} end
under = (below(top) * above(bot)):roughen(3, 14, 131, 0)
pUnder = pile{{"Prussian blue",0.45},{"raw umber",1.6},{"bone black",0.5},{"yellow ochre",0.7},{"green earth",0.3}}
work(under, {hand="body", tool="filbert 6", pile=pUnder, angle=function(x,y) return 0.5*math.sin(x/20) end, angle_jitter=0.5, coverage=3.5, load=0.95, fill=true, length={10,30}, edge="soft"})
-- the stub where the far-shore reflection runs under the near bank
local stub = rect(452, 460, 30, 20) * refl2:grow(12)
work(stub, {hand="detail", tool={kind="flat", width=4}, pile=pR1, coverage=3, load=0.9, fill=true})
EOF
timeout 1200 bin/easel do -f $TMPDIR/c52.lua && bin/easel look --crop 0,380,500,560

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Accident: the under-bank mask was open-ended past its last curve point (above(bot) with bot ending at x=470), so a 20-unit dark column ran from the bank to the bottom edge at x~463-482. Lesson: point-list curves must span past the whole canvas width. Letting it dry, then I'll repaint that strip in the water colours of each height, two coats, and blend horizontally into the surround. The dark bank itself reads well as a low bushy shore."
timeout 600 bin/easel do 'print(wait(48*60)); print(drying(472,520), drying(472,650), drying(200,455))'

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "The patch over the column covered the dark but reads as a pale vertical strip: patching a smooth graded surface locally never matches. Decision: once this sets, repaint the whole open water right of the tree reflection as a second full layer (glow, reflected cloud, blue-grey) and blend it all wet, so there is no local patch."
timeout 600 bin/easel do 'print(wait(40*60)); print(drying(472,520), drying(472,650), drying(700,650))'

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Day 24: the whole open water repainted as one wet layer in six graded bands (glow, lavender, reflected cloud pink, blue-grey) and blended horizontally with vertical seam blends. The strip is gone; water is calm and even now. A pale sliver remains under the bank at x 300-470, y~475. Next while it dries: fix the sliver and the peach smear near the treetop."
bin/easel look --crop 180,120,320,220 --grid 10

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Sliver under the bank covered with a flat detail fill over the tacky dark. Now the boat: a dark punt with a standing figure poling, right of centre on the lavender water, silhouetted against the glow's reflection."
cat > $TMPDIR/c73.lua <<'EOF'
hull = outline{{612,544,"c"},{628,549},{660,551},{694,549},{708,543,"c"},{700,547},{690,552},{662,555},{630,554},{618,550}, closed=true, char="firm", seed=151, amount=0.4}
hullM = hull:mask()
fig = body_of{spine={{672,545},{671,532},{670,522},{669,514}}, widths={5.5,5,5.5,4.2}, limbs={{{669,512},{669,506},widths={3.4,3.4}}, {{670,524},{664,530},{659,536},widths={2.2,2,1.8}}, {{670,522},{676,528},{681,531},widths={2,1.8,1.6}}}, char="soft", seed=152}
figM = fig:mask()
pBoat = pile{{"raw umber",1.5},{"bone black",0.7},{"smalt",0.3},{"red earth",0.2}}
work(hullM, {hand="detail", tool={kind="round", width=2.5, point=0.4}, pile=pBoat, coverage=4, load=0.95, fill=true})
work(figM, {hand="detail", tool={kind="round", width=2, point=0.4}, pile=pBoat, coverage=4, load=0.95, fill=true})
local r = brush{kind="rigger", width=1.6, point=1}
r:load(pBoat, 0.8)
r:stroke({{690,488},{676,520},{662,552},{656,566}}, {pressure={0.55,0.45}, ramps={0.05,0.1}})
EOF
timeout 1200 bin/easel do -f $TMPDIR/c73.lua && bin/easel look --crop 580,470,760,600

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Day 27. Boat and punter painted as a solid silhouette with a pole; reflection laid as broken horizontal flat strokes and softened with a small badger (the blend over dry paint showed the weave as a lattice around it - acceptable at viewing distance). Whole view: needs a focus of light. Adding the sun's glow low in the sky between the last cloud and the hills, left of the boat, with its shimmer path in the water so the boat sits against it. Then: darker, warmer tree with a rim of light, darker reflection with ripple breaks, reeds in the foreground."
timeout 60 bin/easel do 'print(drying(560,410), drying(560,500), drying(660,540))'

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Another mistake: an unclipped badger along the patch edge caught the freshly painted wet tree top and dragged green-grey wisps into the sky (around 400-490, 340-410). Rule for myself: no unclipped blends anywhere near wet dark paint. Letting everything dry, then covering the wisps with opaque sky colour, clipped, and restating the small tree crown."
timeout 600 bin/easel do 'print(wait(4*24*60)); print(drying(450,390), drying(420,380), drying(360,390), drying(660,540))'

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
cat > $TMPDIR/c92.lua <<'EOF'
print(wait(2*24*60))
local top = {{-10,628}}
local x = -10
while x < 420 do
  x = x + rand(8, 22)
  local base = 628 + (x+10) * 0.08 + ((x > 250) and (x-250)*0.35 or 0)
  top[#top+1] = {x, base + rand(-7, 4)}
end
top[#top+1] = {440, 730}
fg = below(top):roughen(3, 14, 181, 0)
pFG = pile{{"raw umber",1.8},{"bone black",0.6},{"Prussian blue",0.25},{"yellow ochre",0.5},{"red earth",0.2}}
work(fg, {hand="body", tool="filbert 10", pile=pFG, angle=function(x,y) return -0.3 + 0.4*math.sin(x/30) end, angle_jitter=0.5, coverage=3.5, load=0.95, fill=true, length={15,40}, edge="soft"})
EOF
timeout 1200 bin/easel do -f $TMPDIR/c92.lua && bin/easel look

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Day 39: foreground bank laid in a dark umber-black, dark mottling blended in wet, reeds with a pointed rigger rising from its edge (the tall ones cross into the pale water and read well), a few ochre grass blades catching light. Next: glints on the water under the glow, a warm rim on the tree edges facing the light, perhaps two birds."
timeout 60 bin/easel do 'print(drying(560,495), drying(600,480))'; bin/easel look --mode value,squint --size 800

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "The lower sky between tree and clouds is a patchwork: the old repair rectangle shows a hard edge at x~550 and the new glow lies on top unevenly. Will let it dry and then repaint the whole low sky band (x 300-1000, y 330-440) as one graded wet layer, clipped out of trees, clouds and hills, and blend it, rather than patching again."
timeout 600 bin/easel do 'print(wait(3*24*60)); print(drying(590,425), drying(450,380), drying(100,690))'; bin/easel look --crop 500,300,1000,460 --grid 20

cd [local path redacted] && export TMPDIR=[local path redacted] TMP=$TMPDIR TEMP=$TMPDIR; 
bin/easel note "Day 47, finishing. Two small birds in the glow above the far hills; faint glints and wind lines on the water. Looking at it whole: the evening holds - dark contre-jour tree and bank on the left, the pale warm opening of sky and water to the right, the punt as the one small accent against the glow's reflection. Weak places I am leaving: the tree reflection is flat and a little green, the bank under the tree runs as a straight dark wall, the boat's reflection shows the weave where it was blended over dry paint. Further patching would do more harm than good. Calling it finished."
timeout 600 bin/easel save; timeout 1500 bin/easel check
